package com.exl.interview.api;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;

@Service
public class TemplateAssessmentService {
 public record RunView(String id,String state,JavaCodeRunner.Result result){}
 public record CriterionMark(String questionId,String criterionId,Integer points,String notes){}
 public record EvaluationInput(List<CriterionMark> marks,String notes,String recommendation,boolean publish){}
 public record RubricRow(String questionId,String question,String criterionId,String label,int maxPoints,String guidance,Integer points,String notes){}
 public record MCQResult(String questionId,String question,String candidateAnswer,String correctAnswer,String explanation,int points,int maxPoints){}
 public record Evaluation(boolean available,String version,String state,List<MCQResult> mcqs,int mcqPoints,int mcqMax,Double codingPoints,int codingMax,String codingState,JavaCodeRunner.Result codingResult,List<RubricRow> rubric,Double total,boolean complete,String notes,String recommendation,String instructions,Long publishedAt){}
 private final JdbcTemplate db;private final ObjectMapper json;private final TemplateCatalogue catalogue;private final JavaCodeRunner runner;private final AtomicBoolean working=new AtomicBoolean();private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"java-coding-worker");t.setDaemon(true);return t;});
 public TemplateAssessmentService(JdbcTemplate db,ObjectMapper json,TemplateCatalogue catalogue,JavaCodeRunner runner){this.db=db;this.json=json;this.catalogue=catalogue;this.runner=runner;}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
 private <T>T decode(String value,Class<T> type){try{return json.readValue(value,type);}catch(Exception e){throw new IllegalStateException(e);}}
 private ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
 @PostConstruct public void recover(){if(catalogue.enabled())db.update("UPDATE coding_runs SET state='ERROR',result=NULL WHERE state='RUNNING'");}
 public RunView queue(String session,String question,String source){catalogue.requireEnabled();String version=catalogue.versionForSession(session);if(version==null)throw bad("This session has no coding template");var item=catalogue.item(version,question);if(!item.kind().equals("CODING"))throw bad("Not a coding question");if(!runner.enabled())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Docker execution is disabled; complete local runner setup first");if(source==null||source.isBlank()||source.length()>20000)throw bad("Provide Java source between 1 and 20,000 characters");if(db.queryForObject("SELECT COUNT(*) FROM coding_runs WHERE session_id=? AND visibility='PUBLIC'",Integer.class,session)>=50)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Sample-run limit reached for this assessment");if(db.queryForObject("SELECT COUNT(*) FROM coding_runs WHERE state IN ('QUEUED','RUNNING')",Integer.class)>=20)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Runner queue is full; try later");String id=UUID.randomUUID().toString();db.update("INSERT INTO coding_runs (id,session_id,question_id,visibility,state,source,created_at) VALUES (?,?,?,'PUBLIC','QUEUED',?,?)",id,session,question,source,System.currentTimeMillis());return new RunView(id,"QUEUED",null);}
 public RunView publicRun(String id,String session){var rows=db.query("SELECT id,state,result FROM coding_runs WHERE id=? AND session_id=? AND visibility='PUBLIC'",(r,n)->new RunView(r.getString(1),r.getString(2),r.getString(3)==null?null:decode(r.getString(3),JavaCodeRunner.Result.class)),id,session);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Sample run not found");return rows.getFirst();}
 @Scheduled(fixedDelayString="${interview.template-poll-ms:1000}",initialDelayString="${interview.template-initial-delay-ms:1000}") public void dispatch(){if(!catalogue.enabled())return;queueFinalRuns();if(!runner.enabled()||!working.compareAndSet(false,true))return;worker.submit(()->{try{process();}finally{working.set(false);}});}
 @PreDestroy public void shutdown(){worker.shutdownNow();}
 public void process(){if(!catalogue.enabled())return;queueFinalRuns();if(!runner.enabled())return;var jobs=db.queryForList("SELECT id,session_id,question_id,visibility,source FROM coding_runs WHERE state='QUEUED' ORDER BY CASE WHEN visibility='HIDDEN' THEN 0 ELSE 1 END,created_at LIMIT 1");if(jobs.isEmpty())return;var job=jobs.getFirst();String id=(String)job.get("id");if(db.update("UPDATE coding_runs SET state='RUNNING' WHERE id=? AND state='QUEUED'",id)==0)return;try{var item=catalogue.item(catalogue.versionForSession((String)job.get("session_id")),(String)job.get("question_id"));var tests=new ArrayList<>(item.publicTests());if(job.get("visibility").equals("HIDDEN"))tests.addAll(item.hiddenTests());var result=runner.run(db.queryForObject("SELECT source FROM coding_runs WHERE id=?",String.class,id),tests);db.update("UPDATE coding_runs SET state=?,result=? WHERE id=?",result.state().equals("COMPLETE")?"DONE":"ERROR",encode(result),id);}catch(Exception e){db.update("UPDATE coding_runs SET state='ERROR' WHERE id=?",id);}}
 public void queueFinalRuns(){if(!catalogue.enabled())return;var sessions=db.queryForList("SELECT s.id,j.template_version FROM sessions s JOIN interviews j ON j.id=s.interview_id WHERE s.state='SUBMITTED' AND j.template_version IS NOT NULL AND NOT EXISTS (SELECT 1 FROM coding_runs c WHERE c.session_id=s.id AND c.visibility='HIDDEN')");for(var session:sessions){String id=(String)session.get("id");for(var item:catalogue.definition((String)session.get("template_version")).items()){if(!item.kind().equals("CODING"))continue;var sources=db.queryForList("SELECT answer FROM answers WHERE session_id=? AND question_id=?",String.class,id,item.id());try{db.update("INSERT INTO coding_runs (id,session_id,question_id,visibility,state,source,created_at,final_key) VALUES (?,?,?,'HIDDEN','QUEUED',?,?,?)",UUID.randomUUID().toString(),id,item.id(),sources.isEmpty()?"":sources.getFirst(),System.currentTimeMillis(),id+":"+item.id());}catch(org.springframework.dao.DuplicateKeyException ignored){}}}}
 public void retryCoding(String session){catalogue.requireEnabled();if("PUBLISHED".equals(db.queryForObject("SELECT COALESCE(MAX(state),'DRAFT') FROM template_evaluations WHERE session_id=?",String.class,session)))throw bad("Published evaluation is frozen");db.update("UPDATE coding_runs SET state='QUEUED',result=NULL WHERE session_id=? AND visibility='HIDDEN' AND state='ERROR'",session);}
 public Evaluation evaluation(String session){String version=catalogue.versionForSession(session);if(version==null)return new Evaluation(false,null,null,List.of(),0,0,null,0,null,null,List.of(),null,false,"","","",null);String state=db.queryForObject("SELECT state FROM sessions WHERE id=?",String.class,session);if(!"SUBMITTED".equals(state))throw new ResponseStatusException(HttpStatus.CONFLICT,"Evaluation is available after submission");queueFinalRuns();var definition=catalogue.definition(version);var answers=new HashMap<String,String>();db.query("SELECT question_id,answer FROM answers WHERE session_id=?",(org.springframework.jdbc.core.RowCallbackHandler)r->answers.put(r.getString(1),r.getString(2)),session);
  var stored=db.queryForList("SELECT * FROM template_evaluations WHERE session_id=?",session);Map<String,Object> saved=stored.isEmpty()?Map.of():stored.getFirst();List<CriterionMark> marks=List.of();if(saved.containsKey("criteria")){try{marks=json.readValue(db.queryForObject("SELECT criteria FROM template_evaluations WHERE session_id=?",String.class,session),new TypeReference<List<CriterionMark>>(){});}catch(Exception e){throw new IllegalStateException(e);}}
  var mcqs=new ArrayList<MCQResult>();var rubric=new ArrayList<RubricRow>();int earned=0,max=0,manual=0;boolean complete=true;for(var item:definition.items()){if(item.kind().equals("MCQ")){int score=Objects.equals(answers.get(item.id()),item.correctAnswer())?item.maxPoints():0;earned+=score;max+=item.maxPoints();mcqs.add(new MCQResult(item.id(),item.text(),answers.get(item.id()),item.correctAnswer(),item.explanation(),score,item.maxPoints()));}for(var criterion:item.rubric()){var mark=marks.stream().filter(m->m.questionId().equals(item.id())&&m.criterionId().equals(criterion.id())).findFirst().orElse(null);if(mark==null||mark.points()==null)complete=false;else manual+=mark.points();rubric.add(new RubricRow(item.id(),item.text(),criterion.id(),criterion.label(),criterion.maxPoints(),criterion.guidance(),mark==null?null:mark.points(),mark==null?"":mark.notes()));}}
  var runs=db.queryForList("SELECT state,result FROM coding_runs WHERE session_id=? AND visibility='HIDDEN'",session);int codingMax=definition.items().stream().filter(q->q.kind().equals("CODING")).mapToInt(q->q.maxPoints()-q.rubric().stream().mapToInt(TemplateCatalogue.Criterion::maxPoints).sum()).sum();String codingState=codingMax==0?"NOT_REQUIRED":runs.isEmpty()?"QUEUED":(String)runs.getFirst().get("state");JavaCodeRunner.Result result=null;Double coding=codingMax==0?0.0:null;if(!runs.isEmpty()){String raw=db.queryForObject("SELECT result FROM coding_runs WHERE session_id=? AND visibility='HIDDEN'",String.class,session);if(raw!=null)result=decode(raw,JavaCodeRunner.Result.class);}if(result!=null&&codingState.equals("DONE")&&result.state().equals("COMPLETE"))coding=Math.round(codingMax*100.0*result.passed()/Math.max(1,result.total()))/100.0;else if(codingMax>0)complete=false;
  Double total=complete?Math.round((earned+manual+coding)*100)/100.0:null;return new Evaluation(true,version,(String)saved.getOrDefault("state","DRAFT"),mcqs,earned,max,coding,codingMax,codingState,result,rubric,total,complete,stored.isEmpty()?"":db.queryForObject("SELECT notes FROM template_evaluations WHERE session_id=?",String.class,session),(String)saved.getOrDefault("recommendation",""),definition.reviewerInstructions(),(Long)saved.get("published_at"));
 }
 @Transactional public Evaluation save(String session,String reviewer,EvaluationInput input){db.queryForObject("SELECT id FROM sessions WHERE id=? FOR UPDATE",String.class,session);var current=evaluation(session);if(!current.available())throw bad("No template evaluation for this session");if(current.state().equals("PUBLISHED"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Published evaluation is frozen");if(input!=null&&input.marks()!=null)input=new EvaluationInput(input.marks().stream().map(m->m==null?null:new CriterionMark(m.questionId(),m.criterionId(),m.points(),m.notes()==null?"":m.notes())).toList(),input.notes()==null?"":input.notes(),input.recommendation(),input.publish());if(input==null||input.marks()==null||input.notes().length()>5000)throw bad("Invalid evaluation");if(input.recommendation()==null||!Set.of("","SHORTLIST","HOLD","REJECT").contains(input.recommendation()))throw bad("Invalid recommendation");var keys=new HashSet<String>();for(var mark:input.marks()){if(mark==null||mark.questionId()==null||mark.criterionId()==null||!keys.add(mark.questionId()+":"+mark.criterionId()))throw bad("Invalid or duplicate criterion");var row=current.rubric().stream().filter(r->r.questionId().equals(mark.questionId())&&r.criterionId().equals(mark.criterionId())).findFirst().orElseThrow(()->bad("Unknown rubric criterion"));if(mark.points()!=null&&(mark.points()<0||mark.points()>row.maxPoints()))throw bad("Criterion score is outside its range");if(mark.notes()==null||mark.notes().length()>1000)throw bad("Criterion notes must be at most 1000 characters");}
  db.update("MERGE INTO template_evaluations (session_id,state,criteria,notes,recommendation,reviewer) KEY(session_id) VALUES (?,'DRAFT',?,?,?,?)",session,encode(input.marks()),input.notes(),input.recommendation(),reviewer);var updated=evaluation(session);if(input.publish()){if(!updated.complete()||input.recommendation().isBlank())throw bad("Score every criterion, choose a recommendation and wait for coding evaluation before publishing");long now=System.currentTimeMillis();db.update("UPDATE template_evaluations SET state='PUBLISHED',published_at=? WHERE session_id=?",now,session);int score=Math.max(1,Math.min(5,(int)Math.round(updated.total()/20)));db.update("MERGE INTO reviews (session_id,reviewer,score,notes,recommendation,reviewed_at) KEY(session_id) VALUES (?,?,?,?,?,?)",session,reviewer,score,input.notes(),input.recommendation(),now);}return evaluation(session);
 }
}
